function validate([a, b]) {
  if (typeof a !== 'string' || typeof b !== 'string') return 'a and b are strings.';
  if (a.length < 1 || a.length > 100 || b.length < 1 || b.length > 100) return 'Each string has 1 to 100 characters.';
  if (!/^[a-z]+$/.test(a) || !/^[a-z]+$/.test(b)) return 'Use lowercase English letters only.';
  return null;
}

