function findLUSlength(a, b) {
  // Try subsequences from the longest length down; the first one found in exactly one string wins.
  const isSubsequence = (s, t) => {
    let k = 0;
    for (const ch of t) if (k < s.length && ch === s[k]) k++;
    return k === s.length;
  };
  for (let length = Math.max(a.length, b.length); length >= 1; length--) {
    for (const source of [a, b]) {
      const chosen = [];
      const search = start => {
        if (chosen.length === length) {
          const candidate = chosen.join('');
          return isSubsequence(candidate, a) !== isSubsequence(candidate, b);
        }
        for (let i = start; i <= source.length - (length - chosen.length); i++) {
          chosen.push(source[i]);
          if (search(i + 1)) return true;
          chosen.pop();
        }
        return false;
      };
      if (search(0)) return length;
    }
  }
  return -1;
}

