function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, size === 'large' ? 2 + Math.floor(rand() * 25) : 1 + Math.floor(rand() * 3));
  const word = n => Array.from({ length: n }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const max = size === 'large' ? 100 : 8;
  const a = word(1 + Math.floor(rand() * max));
  const roll = rand();
  let b;
  if (roll < 0.25) b = a;
  else if (roll < 0.45) b = a.split('').filter(() => rand() < 0.7).join('') || a[0];
  else b = word(1 + Math.floor(rand() * max));
  return rand() < 0.5 ? [a, b] : [b, a];
}
